public class CasePriorityHandler {
    public static void handleBeforeInsert(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();

        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, String> accountRatingById = new Map<Id, String>();
        List<Account> accounts = [SELECT Id, Rating FROM Account WHERE Id IN :accountIds];

        for (Account account : accounts) {
            accountRatingById.put(account.Id, account.Rating);
        }

        for (Case c : newCases) {
            if (c.AccountId != null && 'Hot'.equals(accountRatingById.get(c.AccountId))) {
                c.Priority = 'High';
            }
        }
    }
}
```

