public class AccountRatingService with sharing {
    private static final Currency HOT_AMOUNT_THRESHOLD = 100000;
    private static final Integer QUERY_BATCH_SIZE = 500;

    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        for (List<Id> chunk : chunkIds(accountIds, QUERY_BATCH_SIZE)) {
            recalculateChunk(new Set<Id>(chunk));
        }
    }

    private static void recalculateChunk(Set<Id> accountIds) {
        List<Opportunity> openOpportunities = [
            SELECT Id, AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
        ];

        Map<Id, Boolean> hasOpenOpportunity = new Map<Id, Boolean>();
        Map<Id, Boolean> hasHotOpportunity = new Map<Id, Boolean>();

        for (Opportunity opp : openOpportunities) {
            if (opp.AccountId == null) {
                continue;
            }

            hasOpenOpportunity.put(opp.AccountId, true);

            if (opp.Amount != null && opp.Amount >= HOT_AMOUNT_THRESHOLD) {
                hasHotOpportunity.put(opp.AccountId, true);
            }
        }

        List<Account> accounts = [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ];

        List<Account> updates = new List<Account>();

        for (Account acc : accounts) {
            String expectedRating;

            if (hasHotOpportunity.containsKey(acc.Id)) {
                expectedRating = 'Hot';
            } else if (hasOpenOpportunity.containsKey(acc.Id)) {
                expectedRating = 'Warm';
            } else {
                expectedRating = 'Cold';
            }

            if (acc.Rating != expectedRating) {
                acc.Rating = expectedRating;
                updates.add(acc);
            }
        }

        if (!updates.isEmpty()) {
            update updates;
        }
    }

    private static List<List<Id>> chunkIds(Set<Id> ids, Integer batchSize) {
        List<List<Id>> chunks = new List<List<Id>>();

        if (ids == null || ids.isEmpty() || batchSize == null || batchSize <= 0) {
            return chunks;
        }

        List<Id> idList = new List<Id>(ids);

        for (Integer i = 0; i < idList.size(); i += batchSize) {
            List<Id> chunk = new List<Id>();
            Integer end = i + batchSize;
            if (end > idList.size()) {
                end = idList.size();
            }

            for (Integer j = i; j < end; j++) {
                chunk.add(idList[j]);
            }

            chunks.add(chunk);
        }

        return chunks;
    }
}
