            if (hotAccounts.contains(acc.Id)) {
                expectedRating = 'Hot';
            } else if (openAccounts.contains(acc.Id)) {
                expectedRating = 'Warm';
            } else {
                expectedRating = 'Cold';
            }
            if (acc.Rating != expectedRating) {
                acc.Rating = expectedRating;
                updates.add(acc);
            }
        }
        if (!updates.isEmpty()) update updates;
    }

    private static List<List<Id>> chunkIds(...)
