CaseTrigger.trigger:
```
// After-update trigger for Case.
// Enqueues a separate CaseSurveyJob for every case that transitions from open to closed.
// The job is responsible for checking whether the case has a Contact and for creating the Task,
// so a failure on one case cannot affect other cases.
trigger CaseTrigger on Case after update {
    // Collect only the case IDs that actually changed from not closed to closed.
    Set<Id> newlyClosedCaseIds = new Set<Id>();

    for (Case c : Trigger.New) {
        Case oldCase = Trigger.OldMap.get(c.Id);
        if (oldCase != null && !oldCase.IsClosed && c.IsClosed) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    // One queueable job per newly closed case.
    for (Id caseId : newlyClosedCaseIds) {
        System.enqueueJob(new CaseSurveyJob(caseId));
    }
}
```
