// Queueable job that creates a CSAT survey Task for a single Case.
// Runs one case at a time so bulk close operations remain isolated.
public class CaseSurveyJob implements Queueable {
    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        // Re-query the case in the async context to get the current data and to avoid
        // creating a survey if the case was reopened or the contact was removed before the job ran.
        Case cs;
        try {
            cs = [SELECT Id, CaseNumber, ContactId, IsClosed FROM Case WHERE Id = :caseId LIMIT 1];
        } catch (QueryException e) {
            // If the record is not visible to this job, do not fail the whole batch.
            return;
        }

        if (cs == null || !cs.IsClosed || String.isBlank(cs.ContactId)) {
            return;
        }

        Task surveyTask = new Task(
            WhatId = cs.Id,
            WhoId = cs.ContactId,
            Subject = 'CSAT survey: ' + cs.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        insert surveyTask;
    }
}
```
