        Map<Id, String> oldCountryByAccount = new Map<Id, String>();
        Map<Id, String> newCountryByAccount = new Map<Id, String>();
        Set<Id> changedAccountIds = new Set<Id>();

        if (oldAccounts == null || newAccounts == null || oldAccounts.size() != newAccounts.size()) return? Could guard.
        for (Integer i = 0; i < newAccounts.size(); i++) {
            Account newAcc = newAccounts.get(i);
            Account oldAcc = oldAccounts.get(i);
            if (newAcc == null || oldAcc == null || newAcc.Id == null) continue;
            if (!stringsEqual(newAcc.BillingCountry, oldAcc.BillingCountry)) {
                changedAccountIds.add(newAcc.Id);
                oldCountryByAccount.put(newAcc.Id, oldAcc.BillingCountry);
                newCountryByAccount.put(newAcc.Id, newAcc.BillingCountry);
            }
        }
        if (changedAccountIds.isEmpty()) return;

        List<Id> accountIds = new List<Id>(changedAccountIds);
        Map<Id, Contact> contactsToUpdate = new Map<Id, Contact>();

        for (Integer i = 0; i < accountIds.size(); i += SOQL_IN_MAX_VALUES) {
            Integer end = Math.min(i + SOQL_IN_MAX_VALUES, accountIds.size());
            List<Id> chunk = accountIds.sublist(i, end);
